<?php $page=max(1,(int)($_GET['page']??1));$total=(int)scalar('SELECT COUNT(*) FROM product_reviews');$reviews=rows('SELECT r.*,p.name product_name FROM product_reviews r JOIN products p ON p.id=r.product_id ORDER BY r.created_at DESC,r.id DESC LIMIT 25 OFFSET '.(($page-1)*25)); ?>
<div class="wg-box"><p><?= $total ?> reviews. Hidden reviews are excluded from public ratings and counts.</p><div class="table-scroll"><table class="admin-table"><thead><tr><th>Product</th><th>Author</th><th>Rating</th><th>Review</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($reviews as $review): ?><tr><td><?= h($review['product_name']) ?></td><td><?= h($review['author_name']) ?><br><small><?= h($review['created_at']) ?></small></td><td><?= (int)$review['rating'] ?> / 5</td><td><?= nl2br(h($review['body'])) ?></td><td><?= h($review['status']) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="moderate_review"><input type="hidden" name="id" value="<?= (int)$review['id'] ?>"><input type="hidden" name="status" value="<?= $review['status']==='published'?'hidden':'published' ?>"><button class="tf-button style-3"><?= $review['status']==='published'?'Hide':'Publish' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></div><div class="admin-toolbar mt-4"><?php if($page>1): ?><a href="?page=<?= $page-1 ?>">Previous</a><?php endif; ?>Page <?= $page ?> of <?= max(1,ceil($total/25)) ?><?php if($page*25<$total): ?><a href="?page=<?= $page+1 ?>">Next</a><?php endif; ?></div>
